PARAMS = {}

def collect(obj, acc):
    if isinstance(obj, bool):
        return
    if isinstance(obj, int):
        acc.append(obj)
    elif isinstance(obj, (list, tuple)):
        for o in obj:
            collect(o, acc)
    elif isinstance(obj, dict):
        for o in obj.values():
            collect(o, acc)

def uniforms(seed, n):
    m = 18446744073709551616
    s = (int(seed) * 2654435761 + 12345) % m
    out = []
    for i in range(n):
        s = (s * 6364136223846793005 + 1442695040888963407) % m
        out.append(((s >> 11) + 0.5) / 9007199254740992.0)
    return out

def build_seq(ex):
    seq = [int(t) for t in ex.get('tokens', [])]
    qs = sorted([[int(q[0]), int(q[1])] for q in ex.get('queries', [])])
    for q in qs:
        t = q[0] + 1
        if 0 <= t < len(seq):
            seq[t] = q[1]
        else:
            seq.append(q[1])
    return seq

def normalize_row(row):
    s = 0.0
    for v in row:
        s += v
    return [v / s for v in row]

def learn(layout, examples, seed):
    k = 16
    seqs = [build_seq(ex) for ex in examples]
    acc = []
    collect(layout, acc)
    for sq in seqs:
        for t in sq:
            acc.append(t)
    V = (max(acc) + 1) if acc else 5
    if V < 1:
        V = 1
    u = uniforms(seed, k * k + k * V)
    A = []
    pos = 0
    for i in range(k):
        A.append(normalize_row(u[pos:pos + k]))
        pos += k
    B = []
    for j in range(k):
        B.append(normalize_row(u[pos:pos + V]))
        pos += V
    prev = None
    for p in range(100):
        cA = [[0.0] * k for i in range(k)]
        cB = [[0.0] * V for j in range(k)]
        paths = []
        for sq in seqs:
            z = 0
            path = []
            for x in sq:
                best = -1.0
                bj = 0
                for j in range(k):
                    bx = B[j][x] if 0 <= x < V else 0.0
                    sc = A[z][j] * bx
                    if sc > best:
                        best = sc
                        bj = j
                cA[z][bj] += 1.0
                if 0 <= x < V:
                    cB[bj][x] += 1.0
                z = bj
                path.append(bj)
            paths.append(path)
        if paths == prev:
            break
        prev = paths
        for i in range(k):
            s = 0.0
            for v in cA[i]:
                s += v
            if s > 0:
                A[i] = [v / s for v in cA[i]]
        for j in range(k):
            s = 0.0
            for v in cB[j]:
                s += v
            if s > 0:
                B[j] = [v / s for v in cB[j]]
    return {'A': A, 'B': B, 'V': V}

def init(layout, params):
    PARAMS['A'] = params['A']
    PARAMS['B'] = params['B']
    PARAMS['V'] = int(params['V'])
    PARAMS['k'] = len(params['A'])
    return 0

def update(state, token):
    A = PARAMS['A']
    B = PARAMS['B']
    V = PARAMS['V']
    k = PARAMS['k']
    z = state
    x = int(token)
    best = -1.0
    bj = 0
    for j in range(k):
        bx = B[j][x] if 0 <= x < V else 0.0
        sc = A[z][j] * bx
        if sc > best:
            best = sc
            bj = j
    return bj

def predict(state):
    A = PARAMS['A']
    B = PARAMS['B']
    V = PARAMS['V']
    k = PARAMS['k']
    z = state
    best = -1.0
    bv = 0
    for v in range(V):
        s = A[z][0] * B[0][v]
        for j in range(1, k):
            s += A[z][j] * B[j][v]
        if s > best:
            best = s
            bv = v
    return bv
